//! Compiles the blog (content/blog/<slug>/<locale>.md) into
//! `$OUT_DIR/blog_posts.rs`, included by src/blog.rs: the Markdown becomes
//! HTML here, so pages cost no parsing in the Worker and a malformed article
//! fails the build instead of a request. Generated by `ocre g blog`; the
//! format is in content/blog/README.md.

use std::{
    env,
    fmt::Write as _,
    fs,
    path::{Path, PathBuf},
};

use pulldown_cmark::{Event, HeadingLevel, Options, Parser, Tag};

/// The default locale (the first of `ocre::locales!`): its file carries the dates.
const DEFAULT_LOCALE: &str = "__DEFAULT_LOCALE__";
const LOCALES_DIR: &str = "locales";
const BLOG_DIR: &str = "content/blog";

struct Text {
    title: String,
    description: String,
    html: String,
    markdown: String,
}

struct Post {
    slug: String,
    published_on: String,
    updated_on: String,
    texts: Vec<Text>,
}

fn main() {
    println!("cargo::rerun-if-changed={BLOG_DIR}");
    println!("cargo::rerun-if-changed={LOCALES_DIR}");
    let locales = locales();
    let mut posts = match fs::read_dir(BLOG_DIR) {
        Ok(entries) => {
            let mut dirs: Vec<PathBuf> =
                entries.map(|entry| entry.expect("content/blog entry").path()).filter(|path| path.is_dir()).collect();
            dirs.sort();
            dirs.iter().map(|dir| post(dir, &locales)).collect::<Vec<_>>()
        }
        Err(_) => vec![],
    };
    // Newest first; same day: by slug, so the order never depends on the file system.
    posts.sort_by(|a, b| b.published_on.cmp(&a.published_on).then_with(|| a.slug.cmp(&b.slug)));

    let mut out = String::new();
    let _ = writeln!(out, "pub const POST_LOCALES: &[&str] = &{locales:?};");
    let latest = posts.iter().map(|post| post.updated_on.as_str()).max().unwrap_or("");
    let _ = writeln!(out, "pub const UPDATED_ON: &str = {latest:?};");
    out.push_str("pub const POSTS: &[Post] = &[\n");
    for post in &posts {
        let _ = writeln!(
            out,
            "    Post {{ slug: {:?}, path: {:?}, published_on: {:?}, updated_on: {:?}, texts: &[",
            post.slug,
            format!("/blog/{}", post.slug),
            post.published_on,
            post.updated_on
        );
        for text in &post.texts {
            let _ = writeln!(
                out,
                "        Text {{ title: {:?}, description: {:?}, html: {:?}, markdown: {:?} }},",
                text.title, text.description, text.html, text.markdown
            );
        }
        out.push_str("    ] },\n");
    }
    out.push_str("];\n");
    let target = Path::new(&env::var("OUT_DIR").expect("OUT_DIR")).join("blog_posts.rs");
    fs::write(target, out).expect("write blog_posts.rs");
}

/// The app's locales, one per `locales/<code>.yml`, default first (only the
/// default locale without translations): every article exists in each.
fn locales() -> Vec<String> {
    let Ok(entries) = fs::read_dir(LOCALES_DIR) else { return vec![DEFAULT_LOCALE.to_owned()] };
    let mut codes: Vec<String> = entries
        .filter_map(|entry| {
            let path = entry.expect("locales entry").path();
            (path.extension()? == "yml").then(|| path.file_stem()?.to_str().map(str::to_owned)).flatten()
        })
        .collect();
    codes.sort_by_key(|code| (code != DEFAULT_LOCALE, code.clone()));
    assert_eq!(codes.first().map(String::as_str), Some(DEFAULT_LOCALE), "locales/{DEFAULT_LOCALE}.yml missing");
    codes
}

fn post(dir: &Path, locales: &[String]) -> Post {
    let slug = dir.file_name().and_then(|name| name.to_str()).expect("UTF-8 directory name").to_owned();
    let valid_slug = !slug.is_empty()
        && !slug.starts_with('-')
        && !slug.ends_with('-')
        && slug.bytes().all(|b| b.is_ascii_lowercase() || b.is_ascii_digit() || b == b'-');
    assert!(valid_slug, "{BLOG_DIR}/{slug}: the directory name is the URL, use a-z, 0-9 and -");
    for entry in fs::read_dir(dir).expect("article directory") {
        let path = entry.expect("article file").path();
        let name = path.file_name().and_then(|name| name.to_str()).unwrap_or_default();
        let known = locales.iter().any(|locale| name == format!("{locale}.md"));
        assert!(
            known,
            "{}: unexpected file, an article is one <locale>.md per locale ({})",
            path.display(),
            locales.join(", ")
        );
    }

    let mut published_on = String::new();
    let mut updated_on = String::new();
    let texts = locales
        .iter()
        .map(|locale| {
            let default = locale == DEFAULT_LOCALE;
            let path = dir.join(format!("{locale}.md"));
            let source = fs::read_to_string(&path)
                .unwrap_or_else(|_| panic!("{}: missing, every article exists in every locale", path.display()));
            let (fields, body) = front_matter(&source, &path);
            let field = |key: &str| fields.iter().find(|(k, _)| k == key).map(|(_, v)| v.clone());
            for (key, _) in &fields {
                let allowed = ["title", "description"].contains(&key.as_str())
                    || (default && ["published", "updated"].contains(&key.as_str()));
                assert!(
                    allowed,
                    "{}: unknown front matter key `{key}` (dates go in {DEFAULT_LOCALE}.md only)",
                    path.display()
                );
            }
            if default {
                published_on =
                    field("published").unwrap_or_else(|| panic!("{}: `published: YYYY-MM-DD` missing", path.display()));
                updated_on = field("updated").unwrap_or_else(|| published_on.clone());
                for date in [&published_on, &updated_on] {
                    assert!(is_date(date), "{}: `{date}` is not a YYYY-MM-DD date", path.display());
                }
                assert!(updated_on >= published_on, "{}: `updated` is before `published`", path.display());
            }
            let required = |key: &str| {
                field(key)
                    .filter(|value| !value.is_empty())
                    .unwrap_or_else(|| panic!("{}: `{key}` missing", path.display()))
            };
            let markdown = body.trim().to_owned();
            assert!(!markdown.is_empty(), "{}: empty article", path.display());
            Text {
                title: required("title"),
                description: required("description"),
                html: html(&markdown, &path),
                markdown,
            }
        })
        .collect();
    Post { slug, published_on, updated_on, texts }
}

/// (`key: value` lines between the opening and closing `---`, the body).
fn front_matter<'a>(source: &'a str, path: &Path) -> (Vec<(String, String)>, &'a str) {
    let rest = source
        .strip_prefix("---\n")
        .or_else(|| source.strip_prefix("---\r\n"))
        .unwrap_or_else(|| panic!("{}: starts with a `---` front matter block", path.display()));
    let end = rest.find("\n---").unwrap_or_else(|| panic!("{}: front matter not closed by `---`", path.display()));
    let fields = rest[..end]
        .lines()
        .filter(|line| !line.trim().is_empty())
        .map(|line| {
            let (key, value) =
                line.split_once(':').unwrap_or_else(|| panic!("{}: `{line}` is not `key: value`", path.display()));
            let value = value.trim();
            let value = value.strip_prefix('"').and_then(|v| v.strip_suffix('"')).unwrap_or(value);
            (key.trim().to_owned(), value.to_owned())
        })
        .collect();
    let body = &rest[end + 4..];
    (fields, body.split_once('\n').map_or("", |(_, body)| body))
}

fn is_date(value: &str) -> bool {
    let bytes = value.as_bytes();
    bytes.len() == 10
        && bytes.iter().enumerate().all(|(i, b)| if i == 4 || i == 7 { *b == b'-' } else { b.is_ascii_digit() })
}

/// The article's HTML. The page's `<h1>` is the title, so the body starts at
/// `##`. Raw HTML in the Markdown is shown as text, never as markup: the page
/// marks the body safe, so an article can never add scripts or embeds.
fn html(markdown: &str, path: &Path) -> String {
    let options = Options::ENABLE_TABLES | Options::ENABLE_STRIKETHROUGH | Options::ENABLE_FOOTNOTES;
    let events: Vec<Event> = Parser::new_ext(markdown, options)
        .map(|event| match event {
            Event::Html(html) | Event::InlineHtml(html) => Event::Text(html),
            event => event,
        })
        .collect();
    let h1 = events.iter().any(|event| matches!(event, Event::Start(Tag::Heading { level: HeadingLevel::H1, .. })));
    assert!(
        !h1,
        "{}: no `# ` heading in the body, the title is the page's h1; start sections at `## `",
        path.display()
    );
    let mut out = String::new();
    pulldown_cmark::html::push_html(&mut out, events.into_iter());
    out
}
